#!/usr/bin/env python3
"""Receipts for PR review skills, and a gate that blocks ticked PR-body boxes without one.

record: PostToolUse(Skill) hook. Appends {step, ts} for tracked skills to a per-session log.
gate:   PreToolUse(Bash) hook. On `gh pr create|edit` with a body, every ticked review box
        needs a receipt newer than both the PR head commit and the last /create-pr start.
"""
import json
import os
import re
import subprocess
import sys
import time
from datetime import datetime
from pathlib import Path

STATE_DIR = Path.home() / ".claude" / "state" / "pr-receipts"
TRACKED = {"create-pr", "scope-check", "dg-pr-adherence-check", "dg-delegated-full-review"}
TICKED_BOX = {
    "scope-check": re.compile(r"-\s*\[[xX]\][^\n]*scope-check"),
    "dg-pr-adherence-check": re.compile(r"-\s*\[[xX]\][^\n]*dg-pr-adherence-check"),
    "dg-delegated-full-review": re.compile(
        r"-\s*\[[xX]\][^\n]*(dg-delegated-full-review|comprehensive review)"
    ),
}
PR_WRITE = re.compile(r"\bgh\s+pr\s+(create|edit)\b")


def receipts_path(session_id: str) -> Path:
    return STATE_DIR / f"{session_id or 'unknown'}.jsonl"


def load_receipts(session_id: str) -> list:
    path = receipts_path(session_id)
    if not path.exists():
        return []
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def record(payload: dict) -> int:
    skill = (payload.get("tool_input") or {}).get("skill", "").split(":")[-1]
    if skill not in TRACKED:
        return 0
    STATE_DIR.mkdir(parents=True, exist_ok=True)
    with receipts_path(payload.get("session_id", "")).open("a") as f:
        f.write(json.dumps({"step": skill, "ts": time.time()}) + "\n")
    return 0


def target_dir(command: str, cwd: str) -> str:
    match = re.match(r"\s*cd\s+(\"[^\"]+\"|'[^']+'|\S+)", command)
    if not match:
        return cwd
    return os.path.expanduser(match.group(1).strip("\"'"))


def body_text(command: str, workdir: str) -> str:
    # Inline bodies (heredocs, --body "...") are part of the command; file bodies are read.
    paths = re.findall(r"(?:--body-file|-F)\s+(\"[^\"]+\"|'[^']+'|\S+)", command)
    paths += re.findall(r"\$\(cat\s+(\"[^\"]+\"|'[^']+'|\S+)\)", command)
    text = command
    for raw in paths:
        path = Path(os.path.expanduser(raw.strip("\"'")))
        if not path.is_absolute():
            path = Path(workdir) / path
        if path.is_file():
            text += "\n" + path.read_text()
    return text


def run(args: list, workdir: str) -> str:
    try:
        out = subprocess.run(args, cwd=workdir, capture_output=True, text=True, timeout=20)
        return out.stdout.strip() if out.returncode == 0 else ""
    except (OSError, subprocess.TimeoutExpired):
        return ""


def head_commit_time(command: str, workdir: str) -> float:
    times = []
    local = run(["git", "log", "-1", "--format=%ct", "HEAD"], workdir)
    if local:
        times.append(float(local))
    if re.search(r"\bgh\s+pr\s+edit\b", command):
        number = re.search(r"\bgh\s+pr\s+edit\s+(\d+)", command)
        args = ["gh", "pr", "view"] + ([number.group(1)] if number else [])
        remote = run(args + ["--json", "commits", "--jq", ".commits[-1].committedDate"], workdir)
        if remote:
            times.append(datetime.fromisoformat(remote.replace("Z", "+00:00")).timestamp())
    return max(times, default=0.0)


def gate(payload: dict) -> int:
    command = (payload.get("tool_input") or {}).get("command", "")
    if not PR_WRITE.search(command):
        return 0
    workdir = target_dir(command, payload.get("cwd") or os.getcwd())
    body = body_text(command, workdir)
    ticked = [step for step, pattern in TICKED_BOX.items() if pattern.search(body)]
    if not ticked:
        return 0

    receipts = load_receipts(payload.get("session_id", ""))
    create_pr_start = max(
        (r["ts"] for r in receipts if r["step"] == "create-pr"), default=0.0
    )
    threshold = max(head_commit_time(command, workdir), create_pr_start)
    missing = [
        step
        for step in ticked
        if not any(r["step"] == step and r["ts"] >= threshold for r in receipts)
    ]
    if not missing:
        return 0

    since = datetime.fromtimestamp(threshold).strftime("%Y-%m-%d %H:%M") if threshold else "ever"
    print(
        "PR body ticks a review box without a matching run. Missing a Skill invocation of: "
        + ", ".join(missing)
        + f" in this session since {since} (the later of the head commit and the last "
        "/create-pr start). Invoke each skill on the current head, or untick its box and "
        "add one line saying why it did not run.",
        file=sys.stderr,
    )
    return 2


def main() -> int:
    mode = sys.argv[1] if len(sys.argv) > 1 else ""
    try:
        payload = json.load(sys.stdin)
        if mode == "record":
            return record(payload)
        if mode == "gate":
            return gate(payload)
    except Exception as error:  # A broken gate must not silently block or silently pass.
        print(f"pr-receipts {mode} failed: {error}", file=sys.stderr)
        return 1
    print(f"usage: pr-receipts.py record|gate (got {mode!r})", file=sys.stderr)
    return 1


if __name__ == "__main__":
    sys.exit(main())

